package com.gomgomapps.math.core;
import java.util.*;import java.math.BigInteger;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenFractionDivisionScopeTest {
 @Test public void normalRoutesUsePublicAnswersAndPreserveElevenFramesAndOldDraft(){
  Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");
  for(String id:List.of("fracDiv","fracDivInt")){assertTrue(GlobalCurriculum.pack(p).inGrade(id,7));CurriculumLimits l=GlobalCurriculum.limits("na-nied-primary-2024-v1",id,7);Generator g=new Generator(new Random(352));List<String>recent=new ArrayList<>();for(int i=0;i<100;i++){Question q=g.next(id,recent,false,l);assertTrue(l.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=PrimaryFractionDivision.read(q);assertNotNull(q.prompt,v);Rational expected=new Rational(v.a,v.b).div(new Rational(v.c,v.d));HelpPlan old=HelpPlan.forQuestion(q);HelpPlan.Draft draft=old.restore(null,q.id);draft.entries.set(0,v.a.toString());draft.stage=1;String version=draft.teachingVersion;q.answers=new String[]{"999"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(expected.toString())).correct());assertFalse(new Checker().check(q,List.of(),List.of("999")).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(11,h.size());assertFalse(h.canTransfer());draft=h.restore(draft.copy(),q.id);assertEquals(version,draft.teachingVersion);assertEquals(1,draft.stage);assertEquals(v.a.toString(),draft.entries.get(0));}}
 }
 @Test public void exactSyntaxAndImmutablePublicOperandsRejectUnrelatedAndNestedForms(){
  for(String raw:List.of("(2/3) / (4/5)","(2/3) ÷ (4/5)","2/3 ÷ 4/5")){Question q=new Question("fracDiv",raw,"poison","999");String prompt=q.prompt;var v=PrimaryFractionDivision.read(q);assertNotNull(v);assertEquals(BigInteger.valueOf(2),v.a);assertEquals(BigInteger.valueOf(3),v.b);assertEquals(BigInteger.valueOf(4),v.c);assertEquals(BigInteger.valueOf(5),v.d);assertTrue(new Checker().check(q,List.of(),List.of("10/12")).correct());assertEquals(prompt,q.prompt);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);}
  Question large=new Question("fracDiv","(1234/5678) / (3456/7890)","poison","999");assertNotNull(PrimaryFractionDivision.read(large));
  String zeroes="0".repeat(99);assertNotNull(PrimaryFractionDivision.read(new Question("fracDiv","(1"+zeroes+"/2"+zeroes+") / (3"+zeroes+"/4"+zeroes+")","poison","999")));Question tooLong=new Question("fracDiv","1".repeat(1100)+"/2 ÷ 1/2","poison","999");assertNull(PrimaryFractionDivision.read(tooLong));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(tooLong,List.of(),List.of("999")).status);
  for(String raw:List.of("((2/3)) / (4/5)","(2/3 / (4/5))","2/3/4/5","2/3 × 4/5","2/0 ÷ 4/5","2/3 ÷ 0/5","2/3 ÷ 4/0","2 ÷ 4/5","2/3 ÷ 2","-2/3 ÷ 4/5")){Question q=new Question("fracDiv",raw,"","999");assertNull(raw,PrimaryFractionDivision.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("999")).status);}
  for(String raw:List.of("(1/4) / (2)","(1/4) / 2","(1/4) ÷ 2","(8/9) / 5","1/4 ÷ 2")){Question q=new Question("fracDivInt",raw,"poison","999");var v=PrimaryFractionDivision.read(q);assertNotNull(raw,v);assertEquals(BigInteger.valueOf(raw.equals("(8/9) / 5")?5:2),v.c);assertEquals(BigInteger.ONE,v.d);assertTrue(new Checker().check(q,List.of(),List.of(raw.equals("(8/9) / 5")?"8/45":"1/8")).correct());}
  for(String raw:List.of("1/4 ÷ 0","1/4 ÷ 1/2","1 ÷ 2","1 1/4 ÷ 2","(1/4) / ((2))","(1/4) / (2","(1/4) / 2)"))assertNull(PrimaryFractionDivision.read(new Question("fracDivInt",raw,"","999")));
 }
 @Test public void publicDomainIsNotLimitedByProperFractionSupplier(){
  String[][] cases={{"0/3 ÷ 4/5","0/1"},{"3/3 ÷ 4/5","5/4"},{"2/3 ÷ 5/4","8/15"},{"5/3 ÷ 2/3","5/2"}};
  for(String[]v:cases){Question q=new Question("fracDiv",v[0],"poison","999");assertNotNull(PrimaryFractionDivision.read(q));assertTrue(new Checker().check(q,List.of(),List.of(v[1])).correct());Rational result=Expression.number(v[1]);assertTrue(new Checker().check(q,List.of(),List.of(result.n.multiply(BigInteger.TWO)+"/"+result.d.multiply(BigInteger.TWO))).correct());q.kind="reduced";assertTrue(new Checker().check(q,List.of(),List.of(v[1])).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of(result.n.multiply(BigInteger.TWO)+"/"+result.d.multiply(BigInteger.TWO))).status);}
  Question whole=new Question("fracDivInt","(5/3) / (2)","poison","999");assertNotNull(PrimaryFractionDivision.read(whole));assertTrue(new Checker().check(whole,List.of(),List.of("5/6")).correct());assertNull(PrimaryFractionDivision.read(new Question("fracDiv","0/3 ÷ 0/5","","999")));
 }
 @Test public void formatsEquivalentAnswersAndPartErrorsKeepStudentRaw(){
  Question q=new Question("fracDiv","(3/4) / (1/2)","poison","999");Checker c=new Checker();for(String input:List.of("3/2","6/4","1.5"))assertTrue(c.check(q,List.of(),List.of(input)).correct());for(String input:List.of("","1+0.5","(1.5)","3/2+0"))assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(input)).status);
  q.answerFormat="fraction";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1.5")).status);q.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("3/2")).status);q.answerFormat="decimalValue";assertTrue(c.check(q,List.of(),List.of("1.5")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("3/2")).status);q.answerFormat="hundredthsFraction";assertTrue(c.check(q,List.of(),List.of("150/100")).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of("3/2")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("")).status);q.answerFormat="";q.kind="reduced";assertTrue(c.check(q,List.of(),List.of("3/2")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("6/4")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1.5")).status);
  Question part=new Question("fracDiv","(2/3) / (4/5)","poison","999");List<String>raw=new ArrayList<>(List.of("7/6","5/7","7/7","10/12"));List<String>before=List.copyOf(raw);assertEquals(1,FractionInput.errorPart(part,raw.get(0)));assertEquals(2,FractionInput.errorPart(part,raw.get(1)));assertEquals(0,FractionInput.errorPart(part,raw.get(2)));assertEquals(0,FractionInput.errorPart(part,raw.get(3)));assertEquals(before,raw);
 }
 @Test public void wholeDivisorHelpCoversPublicGeneralValuesWithoutChangingLegacyFrames(){
  String[]labels={"첫 분자 a = ","첫 분모 b = ","둘째 분자 c = ","둘째 분모 d = ","역수의 분자 e = d = ","역수의 분모 f = c = ","계산한 분자 N = a × e = ","계산한 분모 D = b × f = ","최대공약수 g = gcd(N, D) = ","최종 분자 = N ÷ g = ","최종 분모 = D ÷ g = "};
  String[]instructions={"첫 번째 분수의 분자를 쓰세요.","첫 번째 분수의 분모를 쓰세요.","자연수를 분자로 쓰세요.","자연수는 분모가 1인 분수로 쓸 수 있습니다. 분모를 쓰세요.","나누는 분수를 뒤집어 역수의 분자를 쓰세요.","역수의 분모에 나누는 수의 분자를 쓰세요.","분자끼리 곱하세요.","분모끼리 곱하세요.","계산한 분자와 분모를 모두 나눌 수 있는 가장 큰 수를 구하세요.","계산한 분자를 최대공약수로 나누세요.","분모도 같은 최대공약수로 나누세요."};
  for(String raw:List.of("(1/3) / 2","(0/3) / 2","(5/3) / 2","(3/3) / 2","0/3 ÷ 2","5/3 ÷ 2","(12345678901234567890/3) / 2")){
   Question q=new Question("fracDivInt",raw,"poison","999");var p=PrimaryFractionDivision.read(q);assertNotNull(p);BigInteger n=p.a.multiply(p.d),d=p.b.multiply(p.c),g=n.gcd(d);String[]values={p.a.toString(),p.b.toString(),p.c.toString(),p.d.toString(),p.d.toString(),p.c.toString(),n.toString(),d.toString(),g.toString(),n.divide(g).toString(),d.divide(g).toString()};HelpPlan h=HelpPlan.forQuestion(q);assertNotNull(raw,h);assertEquals(11,h.size());assertFalse(h.canTransfer());assertEquals(Integer.valueOf(9),q.studyGuide.resultNumeratorFrame);assertEquals(Integer.valueOf(10),q.studyGuide.resultDenominatorFrame);assertEquals("fraction-product-relations-v1",q.studyGuide.teachingVersion);
   for(int i=0;i<11;i++){assertEquals(instructions[i],h.step(i).instruction);assertEquals(labels[i],h.step(i).before);assertEquals("",h.step(i).after);assertTrue(h.step(i).options.isEmpty());assertEquals(values[i],q.studyGuide.frames.get(i).expected);assertTrue(h.step(i).accepts(values[i]));}
   HelpPlan.Draft saved=new HelpPlan.Draft();saved.questionId=q.id;saved.teachingVersion="fraction-product-relations-v1";saved.entries=new ArrayList<>(Arrays.asList(values));saved.stage=11;HelpPlan.Draft restored=h.restore(saved.copy(),q.id);assertEquals(11,restored.stage);assertEquals(Arrays.asList(values),restored.entries.subList(0,11));assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
  }
 }
 @Test public void commonDivisionHelpUsesExactPublicValuesAndKeepsLegacyDraft(){
  String[]labels={"첫 분자 a = ","첫 분모 b = ","둘째 분자 c = ","둘째 분모 d = ","역수의 분자 e = d = ","역수의 분모 f = c = ","계산한 분자 N = a × e = ","계산한 분모 D = b × f = ","최대공약수 g = gcd(N, D) = ","최종 분자 = N ÷ g = ","최종 분모 = D ÷ g = "};
  String[]instructions={"첫 번째 분수의 분자를 쓰세요.","첫 번째 분수의 분모를 쓰세요.","두 번째 분수의 분자를 쓰세요.","두 번째 분수의 분모를 쓰세요.","나누는 분수를 뒤집어 역수의 분자를 쓰세요.","역수의 분모에 원래 분자를 쓰세요.","분자끼리 곱하세요.","분모끼리 곱하세요.","계산한 분자와 분모를 모두 나눌 수 있는 가장 큰 수를 구하세요.","계산한 분자를 최대공약수로 나누세요.","분모도 같은 최대공약수로 나누세요."};
  for(String raw:List.of("(1/3) / (2/3)","(0/3) ÷ (2/3)","(5/3) ÷ (2/3)","(3/3) ÷ (2/3)","2/3 ÷ 4/5","(6/12) ÷ (4/8)","(12345678901234567890/3) ÷ (1/2)","(4000000000/3) ÷ (1/4000000000)")){
   Question q=new Question("fracDiv",raw,"poison","999");var p=PrimaryFractionDivision.read(q);assertNotNull(p);BigInteger n=p.a.multiply(p.d),d=p.b.multiply(p.c),g=n.gcd(d);String[]values={p.a.toString(),p.b.toString(),p.c.toString(),p.d.toString(),p.d.toString(),p.c.toString(),n.toString(),d.toString(),g.toString(),n.divide(g).toString(),d.divide(g).toString()};HelpPlan h=HelpPlan.forQuestion(q);assertNotNull(raw,h);assertEquals(11,h.size());assertFalse(h.canTransfer());assertEquals(Integer.valueOf(9),q.studyGuide.resultNumeratorFrame);assertEquals(Integer.valueOf(10),q.studyGuide.resultDenominatorFrame);assertEquals("primary-fraction-relations-v1",q.studyGuide.teachingVersion);
   for(int i=0;i<11;i++){assertEquals(instructions[i],h.step(i).instruction);assertEquals(labels[i],h.step(i).before);assertEquals("",h.step(i).after);assertTrue(h.step(i).options.isEmpty());assertEquals(values[i],q.studyGuide.frames.get(i).expected);assertTrue(raw+" frame "+i,h.step(i).accepts(values[i]));}
   HelpPlan.Draft saved=new HelpPlan.Draft();saved.questionId=q.id;saved.teachingVersion="primary-fraction-relations-v1";saved.entries=new ArrayList<>(Arrays.asList(values));saved.stage=11;HelpPlan.Draft restored=h.restore(saved.copy(),q.id);assertEquals(11,restored.stage);assertEquals(Arrays.asList(values),restored.entries.subList(0,11));assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
  }
 }
}
